    if len(rows)>=2:
        bg=g[rows[0]][0]
        period=rows[1]-rows[0]
        for r in range(h):
            if r in rows: continue
            for c in range(w):
                vals=[g[rr][c] for rr in range(h) if rr%period==r%period and g[rr][c]!=bg]
                if vals: g[r][c]=vals[0]
        return g
    cols=[c for c in range(w) if len({g[r][c] for r in range(h)})==1]
    if len(cols)>=2:
        bg=g[0][cols[0]]; period=cols[1]-cols[0]
        for c in range(w):
            if c in cols: continue
            for r in range(h):
                vals=[g[r][cc] for cc in range(w) if cc%period==c%period and g[r][cc]!=bg]
                if vals: g[r][c]=vals[0]
        return g
    # Single horizontal delimiter: repeat the tile of height delimiter row index.
    if rows:
        p=rows[0]
        for r in range(p,h):
            for c in range(w):
                if g[r][c]==g[0][0]:
                    candidates=[rr for rr in range(p) if g[rr][c]!=g[0][0] and rr==r%p]
                    if candidates: g[r][c]=g[candidates[0]][c]
        return g
    if cols:
        p=cols[0]
        for c in range(p,w):
            for r in range(h):
                if g[r][c]==g[0][0]:
                    rr=r
                    if g[rr][c-p]!=g[0][0]: g[r][c]=g[rr][c-p]
        return g
    return g

