    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    # Horizontal stripe template: separator-colored rows reveal repeated vertical pattern.
    rows=[r for r in range(h) if len(set(g[r]))==1]
    if rows:
        bg=g[rows[0]][0]
        nonbg=[(r,c,v) for r in range(h) for c,v in enumerate(g[r]) if v!=bg]
        # For each non-background mark, copy its horizontal/vertical pattern into blanks
        # based on the repeating unit indicated by repeated separator rows.
        period=(rows[1]-rows[0]) if len(rows)>1 else rows[0]
        if period>0:
            for r in range(h):
                if r in rows: continue
                sources=[(rr,c,v) for rr,c,v in nonbg if rr%period==r%period]
                for rr,c,v in sources:
                    if g[r][c]==bg: g[r][c]=v
            # when the only template occurrence has a marked cell, repeat its within-tile row
            if len(rows)==1:
                sep=rows[0]
                for r in range(sep+1,h):
                    src=(r-sep-1)%sep
                    for c in range(w):
                        if g[r][c]==bg and g[src][c]!=bg: g[r][c]=g[src][c]
        return g
    cols=[c for c in range(w) if len({g[r][c] for r in range(h)})==1]
    if cols:
        bg=g[0][cols[0]]; period=(cols[1]-cols[0]) if len(cols)>1 else cols[0]
        if period>0:
            for c in range(w):
                if c in cols: continue
                for r in range(h):
                    for cc in range(w):
                        if cc%period==c%period and g[r][cc]!=bg and g[r][c]==bg:
                            g[r][c]=g[r][cc]; break
        return g
    return g

