    colors={}
    for r in uniform_rows: colors.setdefault(g[r][0],[]).append(r)
    candidates=[(rs,color) for color,rs in colors.items() if len(rs)>=2]
    if candidates:
        rs,bg=max(candidates,key=lambda x:len(x[0]))
        period=rs[1]-rs[0]
        for r in range(h):
            for c in range(w):
                if g[r][c]==bg:
                    source=[rr for rr in range(h) if (rr-r)%period==0 and g[rr][c]!=bg]
                    if source: g[r][c]=g[source[0]][c]
        return g
    uniform_cols=[c for c in range(w) if len({g[r][c] for r in range(h)})==1]
    colors={}
    for c in uniform_cols: colors.setdefault(g[0][c],[]).append(c)
    candidates=[(cs,color) for color,cs in colors.items() if len(cs)>=2]
    if candidates:
        cs,bg=max(candidates,key=lambda x:len(x[0]))
        period=cs[1]-cs[0]
        for c in range(w):
            for r in range(h):
                if g[r][c]==bg:
                    source=[cc for cc in range(w) if (cc-c)%period==0 and g[r][cc]!=bg]
                    if source: g[r][c]=g[r][source[0]]
        return g
    # A single broad separator row marks the boundary before the repeated tile.
    if h==9 and w==9 and all(x==0 for x in g[4]):
